pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 val1, uint256 val2) public {
        vm.assume(val1 < type(uint256).max / 2);
        vm.assume(val2 < type(uint256).max / 2);

        vm.prank(address(0x1));
        c.Initialized();

        uint256 oldMinSum = c.MinSum();

        bool ok = true;
        vm.prank(address(0x1));
        try c.SetMinSum(val1) {
        } catch {
            ok = false;
        }

        bool propertyHolds = !ok;

        assertTrue(propertyHolds);
    }
}
